class MemberExpressionsTest {

    @Test
    void 값이_있으면_조건이_나온다() {
        assertThat(MemberExpressions.ageGoe(20))
                .hasToString("member1.age >= 20");
    }

    @Test
    void 값이_없으면_null() {
        assertThat(MemberExpressions.ageGoe(null)).isNull();
    }

    @Test
    void 빈_문자열도_null() {
        assertThat(MemberExpressions.usernameEq("")).isNull();
        assertThat(MemberExpressions.usernameEq("   ")).isNull();
    }

    @Test
    void 합쳐도_안전하다() {
        assertThat(MemberExpressions.ageBetween(null, null)).isNull();
        assertThat(MemberExpressions.ageBetween(null, 30))
                .hasToString("member1.age <= 30");
    }
}

