class MemberJpaRepositoryTest extends QuerydslTestSupport {

    @Autowired MemberJpaRepository repository;

    @Test
    void 조건_없으면_전부() {
        List<MemberTeamDto> r = repository.search(new MemberSearchCondition());
        assertThat(r).hasSize(10);
    }

    @Test
    void 나이_범위() {
        MemberSearchCondition cond = new MemberSearchCondition();
        cond.setAgeGoe(20);
        cond.setAgeLoe(30);

        List<MemberTeamDto> r = repository.search(cond);
        assertThat(r).extracting("username")
                .containsExactlyInAnyOrder("m2", "m3", "m6", "m9", "m10");
    }

    @Test
    void 팀_없는_회원도_나온다() {
        MemberSearchCondition cond = new MemberSearchCondition();
        cond.setAgeGoe(20);

        List<MemberTeamDto> r = repository.search(cond);
        assertThat(r).extracting("teamName").contains((String) null);
    }
}

