@Component
public class SqlCounter implements StatementInspector {

    private final List<String> statements = new ArrayList<>();

    @Override
    public String inspect(String sql) {
        statements.add(sql);
        return sql;
    }

    public void clear() { statements.clear(); }
    public int count() { return statements.size(); }
    public List<String> all() { return List.copyOf(statements); }
}

# application.yml
spring:
  jpa:
    properties:
      hibernate:
        session_factory:
          statement_inspector: study.querydsl.test.SqlCounter

@Test
void 문장_검증() {
    em.clear();
    sqlCounter.clear();

    MemberSearchCondition cond = new MemberSearchCondition();
    cond.setAgeGoe(20);
    cond.setAgeLoe(30);
    repository.search(cond);

    assertThat(sqlCounter.count()).isEqualTo(1);
    assertThat(sqlCounter.all().get(0))
            .contains("left join")
            .contains("age>=")
            .contains("age<=");
}

