@ParameterizedTest
@MethodSource("conditions")
void 모든_조합(MemberSearchCondition cond, int expected) {
    em.clear();
    assertThat(repository.search(cond)).hasSize(expected);
}

static Stream<Arguments> conditions() {
    return Stream.of(
            arguments(cond(null, null, null, null), 10),
            arguments(cond("m1", null, null, null), 1),
            arguments(cond(null, "teamA", null, null), 4),
            arguments(cond(null, null, 20, null), 6),
            arguments(cond(null, null, null, 20), 5),
            arguments(cond(null, "teamB", 20, 30), 2));
}

